// resolve_card_field resolves the columns of `Card`.
fn resolve_card_field(_ graphql.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
	return parents.map(graphql.Resolved(card_value((it as CardNode).card, info.field_name)))
}

fn card_value(row models.Card, field string) graphql.Value {
	return match field {
		'id' { graphql.Value(row.id.str()) }
		'number' { graphql.Value(string(row.number)) }
		'ownerID' { graphql.Value(row.owner_id.str()) }
		else { graphql.null }
	}
}

// graphql_args applies the arguments of a `Card` list: `where`, `orderBy`,
// `limit` and `offset`.
fn (q CardQuery) graphql_args(args map[string]graphql.Value) !CardQuery {
	mut next := q
	if w := args['where'] {
		if w is map[string]graphql.Value {
			next = next.where(...card_where(w)!)
		}
	}
	if o := args['orderBy'] {
		if o is map[string]graphql.Value {
			field := (o['field'] or { graphql.null }).as_string()
			column := match field {
				'ID' { 'id' }
				'NUMBER' { 'number' }
				'OWNER_ID' { 'owner_id' }
				else { '' }
			}
			next.query = load.Query{
				...next.query
				order: column
				desc:  (o['direction'] or { graphql.null }).as_string() == 'DESC'
			}
		}
	}
	if limit := args['limit'] {
		if limit is int {
			next = next.limit(limit)
		}
	}
	if offset := args['offset'] {
		if offset is int {
			next = next.offset(offset)
		}
	}
	return next
}

// card_where returns the conditions of a `CardWhereInput`.
fn card_where(w map[string]graphql.Value) ![]load.Cond {
	mut conds := []load.Cond{}
	for key, v in w {
		if v is graphql.Null {
			continue
		}
		match key {
			'id' { conds << load.eq('id', gql_int_id(v)!) }
			'idNEQ' { conds << load.ne('id', gql_int_id(v)!) }
			'idIn' { conds << load.in_ints('id', gql_int_ids(v)!) }
			'idNotIn' { conds << load.not_in_ints('id', gql_int_ids(v)!) }
			'idGT' { conds << load.gt('id', gql_int_id(v)!) }
			'idGTE' { conds << load.ge('id', gql_int_id(v)!) }
			'idLT' { conds << load.lt('id', gql_int_id(v)!) }
			'idLTE' { conds << load.le('id', gql_int_id(v)!) }
			'number' { conds << load.eq('number', v.as_string()) }
			'numberNEQ' { conds << load.ne('number', v.as_string()) }
			'numberIn' { conds << load.in_strings('number', gql_strings(v)) }
			'numberNotIn' { conds << load.not_in_strings('number', gql_strings(v)) }
			'numberGT' { conds << load.gt('number', v.as_string()) }
			'numberGTE' { conds << load.ge('number', v.as_string()) }
			'numberLT' { conds << load.lt('number', v.as_string()) }
			'numberLTE' { conds << load.le('number', v.as_string()) }
			'numberContains' { conds << load.contains('number', v.as_string()) }
			'numberHasPrefix' { conds << load.has_prefix('number', v.as_string()) }
			'numberHasSuffix' { conds << load.has_suffix('number', v.as_string()) }
			'ownerID' { conds << load.eq('owner_id', gql_int_id(v)!) }
			'ownerIDNEQ' { conds << load.ne('owner_id', gql_int_id(v)!) }
			'ownerIDIn' { conds << load.in_ints('owner_id', gql_int_ids(v)!) }
			'ownerIDNotIn' { conds << load.not_in_ints('owner_id', gql_int_ids(v)!) }
			else {}
		}
	}
	return conds
}

// resolve_category_field resolves the columns of `Category`.
fn resolve_category_field(_ graphql.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
	return parents.map(graphql.Resolved(category_value((it as CategoryNode).category, info.field_name)))
}

fn category_value(row models.Category, field string) graphql.Value {
	return match field {
		'id' { graphql.Value(row.id.str()) }
		'name' { graphql.Value(string(row.name)) }
		'parentID' {
			if v := row.parent_id { graphql.Value(v.str()) } else { graphql.null }
		}
		else { graphql.null }
	}
}

// graphql_args applies the arguments of a `Category` list: `where`, `orderBy`,
